extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	if FileAccess.file_exists("user://savegame.json"):
		DirAccess.remove_absolute("user://savegame.json")

	var title := await instantiate_main_scene()
	if not check("main_scene", title != null, "La scena principale deve caricarsi senza errori"):
		return

	var continue_btn := find_by_name(title, "ContinueButton") as Button
	var new_game_btn := find_by_name(title, "NewGameButton") as Button

	if not check("buttons", continue_btn != null and new_game_btn != null, "TitleScreen deve contenere ContinueButton e NewGameButton"):
		return

	check("continue_hidden", continue_btn.visible == false, "Se user://savegame.json non esiste, ContinueButton deve essere nascosto")

	await wait_frames(5)
	check("new_game_focused", new_game_btn.has_focus(), "Se user://savegame.json non esiste, NewGameButton deve ricevere il focus")

	click_button(new_game_btn)
	await wait_seconds(1.0)
	var current := current_scene_path()
	check("scene_changed", current == "res://story/story_screen.tscn", "Premendo Nuova partita la scena deve passare a res://story/story_screen.tscn (scena attuale: %s)" % current)

